head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.fr_SecuGrpId = "ST";
scwin.nColCnt = 0;
scwin.vInValidCol4 = 0; // 법인등록번호
scwin.vInValidCol7 = 0; // 지정일
scwin.vMsg = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd"); // 오늘날짜
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
        let url = frame.srcUrl;
        let arr = url.split("?");
        if (arr.length > 1) {
            MaxTab_01.setSelectedTabIndex(2);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05975.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    // TAB 1
    MaxTab_01.setSelectedTabIndex(1);

    // TAB 2
    await scwin.setComboComTp(dts_ComTp);
    cmb_COM_TP.setSelectedIndex(0);
    edt_SDATE.setValue("19000101"); // 일주일전 날짜 	cGetMinusDate2(vCurDate, 365*2);
    edt_EDATE.setValue(scwin.vCurDate); // 현재날짜
    // TAB 3
    cmb_COM_TP3.setSelectedIndex(0);

    // Common Setting
    await scwin.setBaseDate();

    // TAB 1
    edt_Date.setValue(dts_BasDate.getCellData(1, "BAS_DD"));
    // TAB 3날
    edt_Date3.setValue(dts_BasDate.getCellData(1, "BAS_DD"));
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
