 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05975.dts_List1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List1_OnLoadCompleted
 * @description dts_List1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List1_OnLoadCompleted = async function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (scwin.isValidCheck() === true) {
            await scwin.listPredateDiff();
        } else {
            txb_Msg.setValue(scwin.vMsg);
            await $c.win.alert(scwin.vMsg);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05975.dts_List1_OnLoadCompleted" });
    }
};

