/**
 * @method
 * @name grd_List1_OnUserColor
 * @description grd List1 On User Color 처리
 * @param {Number} row 행 인덱스
 * @param {String} eventId eventId
 * @returns {void}
 * @hidden N
 */
scwin.grd_List1_OnUserColor = function(row, eventId) {
    try {
        let colorName = "#FF40D0";
        if (row === scwin.vInValidCol4) {
            if (eventId === "acolor4" || eventId === "acolor5") {
                return colorName;
            } else {
                if (row % 2 === 0) return "#f2f5f9";

                else return "#ffffff";
            }
        }
        if (row === scwin.vInValidCol7) {
            if (eventId === "acolor7" || eventId === "acolor8" || eventId === "acolor9") {
                return colorName;
            } else {
                if (row % 2 === 0) return "#f2f5f9";

                else return "#ffffff";
            }
        }
        if (row % 2 === 0) return "#f2f5f9";

        else return "#ffffff";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05975.grd_List1_OnUserColor" });
    }
};

/**
 * @method
 * @name grd_List2_OnUserColor
 * @description grd List2 On User Color 처리
 * @param {Number} row 행 인덱스
 * @param {String} eventId eventId
 * @returns {void}
 * @hidden N
 */
scwin.grd_List2_OnUserColor = function(row, eventId) {
    try {
        let colorName = "#77FF88"; // 11FF00";
        if (scwin.nColCnt > 0) {
            if (eventId === "acolor7") {
                if (dts_List2.getCellData(row, "DISCLS_COM_ABBRV") !== dts_List2.getCellData(row, "COM_ABBRV") && dts_List2.getCellData(row, "COM_ABBRV") !== "") {
                    return colorName; // 연두색
                } else {
                    if (row % 2 === 0) return "#f2f5f9";

                    else return "#ffffff";
                }
            }
        }
        if (row % 2 === 0) return "#f2f5f9";

        else return "#ffffff";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05975.grd_List2_OnUserColor" });
    }
};

