/**
 * @method
 * @name setBaseDate
 * @description set Base Date 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setBaseDate = async function() {
    url += "&inputMessageId=KOSDAQ_VENTBZ_STAT_INOUT&outputMessageId=KOSDAQ_VENTBZ_STAT_INOUT";
    url += "&BAS_DD=" + edt_Date.getValue();
    const sbmOptions = {
        id : "sbm_dts_BasDate",
        action : "/SectionTypeChange.do",
        ref : "",
        target : "dts_BasDate=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setComboComTp
 * @description set Combo Com Tp 처리
 * @param {*} dts_Cod dts_Cod
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setComboComTp = async function(dts_Cod) {
    const arrCid = [{
        cid: "SME_EMS_TP_CD",
        cnm: "cmb_COM_TP"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        strCbd = "(null)^전체";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    /*
    	코스닥상장 벤처 기업 현황
     */
    txb_Msg.setValue('');
    url += "&inputMessageId=KOSDAQ_VENTBZ_STAT_INOUT&outputMessageId=KOSDAQ_VENTBZ_STAT_INOUT";
    url += "&ISUR_CD=" + txb_IsurCd.getValue();
    url += "&BAS_DD=" + edt_Date.getValue();
    const sbmOptions = {
        id : "sbm_dts_List1",
        action : "/SectionTypeChange.do",
        ref : "",
        target : "dts_List1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listPredateDiff
 * @description list Predate Diff 처리
 * @returns {Promise<void>}
 * @hidden N
