scwin.listPredateDiff = async function() {
    url += "&inputMessageId=KOSDAQ_VENTBZ_SME_EMS_TP_STAT_INOUT&outputMessageId=KOSDAQ_VENTBZ_SME_EMS_TP_STAT_INOUT";
    url += "&BAS_DD=" + edt_Date.getValue();
    const sbmOptions = {
        id : "sbm_dts_PreDiff",
        action : "/SectionTypeChange.do",
        ref : "",
        target : "dts_PreDiff=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const diffCntRatio = Math.round((dts_PreDiff.getCellData(1, "BAS_DD_CNT") - dts_PreDiff.getCellData(1, "PRE_BAS_DD_CNT")) / dts_PreDiff.getCellData(1, "PRE_BAS_DD_CNT") * 100);
    let msg = '* 마감 시 전일 ' + dts_PreDiff.getCellData(1, "PRE_BAS_DD_CNT") + '건 대비 ' + dts_PreDiff.getCellData(1, "BAS_DD_CNT") + '건 ' + diffCntRatio + '% 차이 발행합니다.';
    if (dts_PreDiff.getCellData(1, "PRE_BAS_DD_CNT") !== 0 && dts_PreDiff.getCellData(1, "BAS_DD_CNT") !== 0 && Math.abs(diffCntRatio) >= 10) {
        txb_Msg.setValue(msg);
        await $c.win.alert(msg);
        return false;
    }
    return true;
};

