/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    let url = frame.srcUrl;
    let arr = url.split("?");
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};

/**
 * @method
 * @name revw
 * @description revw 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.revw = async function() {
    const vErrMsg = "";
    const vErrCnt = 0;
    if (edt_Date.getValue() === "") {
        await $c.win.alert("[일자]를 입력하세요.");
        edt_Date.focus();
        return;
    }
    await scwin.listPredateDiff();
    let res = window.confirm("[마감] 처리하겠습니까?");
    if (res) {
        await scwin.trsRevw('Y');
    }
};

/**
 * @method
 * @name reCls
 * @description re Cls 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reCls = async function() {
    res = window.confirm("[재마감] 처리하겠습니까?");
    if (res) {
        await scwin.trsRevw('N');
        await scwin.listSync();
    }
};

/**
 * @method
 * @name isValidCheck
 * @description is Valid Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.isValidCheck = function() {
    scwin.vInValidCol4 = 0;
    scwin.vInValidCol7 = 0;
    for (let j = 1; j < dts_List1.getRowCount(); j++) {
        if (dts_List1.getCellData(j, "VALID_ISUR_CD") === "N") {
            scwin.vInValidCol4 = j;
            scwin.vMsg = j + "번 '" + dts_List1.getCellData(j, "COM_NM") + "' 종목코드 또는 법인등록번호가 유효하지 않습니다.\n\n";
            return false;
        }
        if (dts_List1.getCellData(j, "VALID_DESIGN_DD") === "N") {
            scwin.vInValidCol7 = j;
            scwin.vMsg = j + "번 '" + dts_List1.getCellData(j, "COM_NM") + "' 벤처 지정일이 해제 예정일보다 이후 입니다.\n\n";
            return false;
        }
        if (scwin.isValidDate(dts_List1.getCellData(j, "VENTBZ_DESIGN_DD")) === false ||
            scwin.isValidDate(dts_List1.getCellData(j, "VENTBZ_RELEAS_SCHDL_DD")) === false ||
            scwin.isValidDate(dts_List1.getCellData(j, "VENTBZ_RELEAS_DD")) === false) {
            scwin.vInValidCol7 = j;
            scwin.vMsg = j + "번 '" + dts_List1.getCellData(j, "COM_NM") + "' 벤처 지정(예정/해제) 날짜가 유효하지 않습니다.\n\n";
            return false;
        }
    }
    scwin.vMsg = '';
    return true;
};

/**
 * @method
 * @name isValidDate
 * @description is Valid Date 처리
 * @param {*} ymd ymd
 * @returns {void}
 * @hidden N
 */
scwin.isValidDate = function(ymd) {
    const year = ymd.substring(0, 4);
    const month = ymd.substring(4, 6);
    const day = ymd.substring(6, 8);
    const d = new Date(year, month - 1, day);
    if (d.getFullYear() === year && $c.ut.lpad((d.getMonth() + 1), 2, '0') === month && $c.ut.lpad(d.getDate(), 2, '0') === day) {
        return true;
    }
    return false;
};
